public function beforeAction($action): bool
{
    $this->data = Json::decode($this->request->getBodyParam('data'));
    return true;
}

public function actionRestoreDb()
{
    $path = $this->data['dbBackupPath'];
    $this->getDb()->restore($path);
    return $this->asJson(['ok' => true]);
}

public function import_preview_page($header, $data) {
    $table = new html_table();
    $table->head = $header;
    $table->data = $data;
    return html_writer::table($table);
}

public function admin_attachment()
{
    $args = func_get_args();
    unset($args[0]);
    $file = implode('/', $args);

    $filePath = WWW_ROOT . 'files' . DS . 'mail' . DS . $file;

    Header('Content-type: application/octet-stream; name=' . $file);
    echo file_get_contents($filePath);
}

